diff --git a/internal/data/image/harbor_artifact.go b/internal/data/image/harbor_artifact.go
index 52645af..0dea798 100644
--- a/internal/data/image/harbor_artifact.go
+++ b/internal/data/image/harbor_artifact.go
@@ -11,10 +11,12 @@ import (
 )

 const (
-	ociManifest    = "application/vnd.oci.image.manifest.v1+json"
-	dockerManifest = "application/vnd.docker.distribution.manifest.v2+json"
-	ociIndex       = "application/vnd.oci.image.index.v1+json"
-	dockerIndex    = "application/vnd.docker.distribution.manifest.list.v2+json"
+	ociManifest       = "application/vnd.oci.image.manifest.v1+json"
+	ociImageConfig    = "application/vnd.oci.image.config.v1+json"
+	dockerManifest    = "application/vnd.docker.distribution.manifest.v2+json"
+	dockerImageConfig = "application/vnd.docker.container.image.v1+json"
+	ociIndex          = "application/vnd.oci.image.index.v1+json"
+	dockerIndex       = "application/vnd.docker.distribution.manifest.list.v2+json"
 )

 type harborPlatform struct {
@@ -100,7 +102,9 @@ func (h *Harbor) readRunnablePlatforms(ctx context.Context, project, repository
 	descriptors := 0
 	var visit func(harborArtifact, int, harborPlatform) error
 	visit = func(a harborArtifact, depth int, expected harborPlatform) error {
-		if depth > 2 || seen[a.Digest] || !strings.EqualFold(a.Type, "IMAGE") || a.ArtifactType != "" || a.Annotations["vnd.docker.reference.type"] == "attestation-manifest" {
+		// Standard container images may declare their image config media type as
+		// artifact_type. Continue rejecting other artifact types and attestations.
+		if depth > 2 || seen[a.Digest] || !strings.EqualFold(a.Type, "IMAGE") || (a.ArtifactType != "" && a.ArtifactType != ociImageConfig && a.ArtifactType != dockerImageConfig) || a.Annotations["vnd.docker.reference.type"] == "attestation-manifest" {
 			return unsupportedArtifact()
 		}
 		if (expected.OS != "" || expected.Architecture != "" || expected.Variant != "") && !supportedPlatform(expected) {
